"use client"

/** @responsibility Owns a deck of windows: which one is focused, whether the deck is a carousel or an overview, the transition between the two, the removal of a dismissed pane, and the keyboard contract that drives it all. */

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  WindowDeckContext,
  composeRefs,
  sortByDocumentPosition,
  type RegisteredWindowDeckPane,
  type WindowDeckMode,
} from "./window-deck-context"
import {
  computeOverviewTiles,
  type WindowDeckOverviewOptions,
  type WindowDeckRect,
  type WindowDeckTile,
} from "./window-deck-layout"
import { longestTransitionMs } from "./window-deck-motion"
import {
  matchesWindowDeckShortcut,
  resolveWindowDeckShortcuts,
  type WindowDeckShortcuts,
} from "./window-deck-shortcuts"

const reducedMotionQuery = "(prefers-reduced-motion: reduce)"

/**
 * How long a pane that came back after its dismissal is still treated as one
 * the host might yet remove, in milliseconds.
 */
const RETAINED_GRACE_MS = 1000

/** Keyboard events already claimed by one deck's shortcut handler. */
const handledShortcutEvents = new WeakSet<KeyboardEvent>()

/** The announcements the deck makes to assistive technology. */
interface WindowDeckLabels {
  /** Announced when the overview opens. */
  overviewOpened: (paneCount: number) => string
  /** Announced when the deck returns to one window. */
  overviewClosed: (paneName: string) => string
  /** Announced when a pane is thrown away or dismissed. */
  paneDismissed: (paneName: string) => string
}

/** The announcements a host may replace, and the strings they default to. */
const windowDeckDefaultLabels: WindowDeckLabels = {
  overviewOpened: (paneCount) => `Overview, ${paneCount} windows`,
  overviewClosed: (paneName) => `${paneName}, full view`,
  paneDismissed: (paneName) => `${paneName} dismissed`,
}

/** Properties accepted by a WindowDeck. */
interface WindowDeckProps extends React.ComponentProps<"div"> {
  /** The focused pane's id, for a controlled deck. */
  activePane?: string
  /** The pane focused initially, for an uncontrolled deck. */
  defaultActivePane?: string
  /** Called whenever the focused pane changes, by any route. */
  onActivePaneChange?: (paneId: string) => void
  /** The presentation mode, for a controlled deck. */
  mode?: WindowDeckMode
  /**
   * The mode the deck opens in, for an uncontrolled deck.
   * @defaultValue "carousel"
   */
  defaultMode?: WindowDeckMode
  /** Called whenever the presentation mode changes, by any route. */
  onModeChange?: (mode: WindowDeckMode) => void
  /**
   * The deck's keymap. Pass a partial map to rebind an action, `false` on an
   * action to drop it, or `false` here to turn off keyboard control
   * entirely. Escape always leaves the overview, as it does in a dialog, and
   * Delete always dismisses the tile the user is focused on.
   * @defaultValue Mod+G toggles the overview; Mod+Arrow moves between panes
   */
  shortcuts?: WindowDeckShortcuts | false
  /**
   * Width of one window, as a CSS length. The deck's scroller is a query
   * container, so size a pane against the deck with `cqw` rather than `%`: a
   * percentage resolves against the rail, whose width is the sum of the
   * panes standing on it.
   * @defaultValue "min(880px, 82cqw)"
   */
  paneWidth?: string
  /**
   * Height of one window, as a CSS length. Panes are the same size by
   * default, which is what keeps the overview a grid of equals; pass "auto"
   * to let each pane take its content's height instead.
   * @defaultValue "100%"
   */
  paneHeight?: string
  /**
   * Column, row, gap, and inset overrides for the overview grid. The deck
   * reads this by value, so an object written inline is safe.
   */
  overviewLayout?: WindowDeckOverviewOptions
  /**
   * Whether a vertical wheel gesture over the deck moves the carousel
   * sideways. Content that scrolls on its own keeps its own gesture.
   * @defaultValue true
   */
  wheelNavigation?: boolean
  /** Overrides for the announcements the deck makes, for localization. */
  labels?: Partial<WindowDeckLabels>
}

/**
 * Whether two tile layouts place every pane identically.
 *
 * @param current - The layout already rendered.
 * @param next - The freshly measured layout.
 * @returns Whether re-rendering would change nothing.
 */
function sameTiles(
  current: Record<string, WindowDeckTile>,
  next: Record<string, WindowDeckTile>,
): boolean {
  const ids = Object.keys(next)

  if (ids.length !== Object.keys(current).length) return false

  return ids.every((id) => {
    const before = current[id]
    const after = next[id]

    return (
      before !== undefined &&
      before.x === after.x &&
      before.y === after.y &&
      before.scale === after.scale
    )
  })
}

/**
 * The scroll offset that centres one pane in the scroller.
 *
 * Both elements are measured in layout coordinates rather than from painted
 * rectangles, so a pane that is currently scaled down — every pane but the
 * focused one — still reports the box the carousel actually reserves for it.
 *
 * @param viewport - The deck's scroller.
 * @param pane - The pane to centre.
 * @returns The scrollLeft that puts the pane in the middle.
 */
function centeredScrollLeft(viewport: HTMLElement, pane: HTMLElement): number {
  return (
    pane.offsetLeft -
    viewport.offsetLeft -
    (viewport.clientWidth - pane.offsetWidth) / 2
  )
}

/**
 * Whether a wheel gesture started somewhere that scrolls vertically on its
 * own, in which case the deck must not take it.
 *
 * @param target - The element the gesture landed on.
 * @param boundary - The deck's scroller, where the search stops.
 * @returns Whether an ancestor consumes the vertical gesture.
 */
function hasScrollableAncestor(
  target: EventTarget | null,
  boundary: HTMLElement,
): boolean {
  let node = target instanceof HTMLElement ? target : null

  while (node && node !== boundary) {
    const overflowY = window.getComputedStyle(node).overflowY

    if (
      (overflowY === "auto" || overflowY === "scroll") &&
      node.scrollHeight > node.clientHeight + 1
    ) {
      return true
    }
    node = node.parentElement
  }

  return false
}

/**
 * A deck of windows the user moves between: a horizontal carousel that
 * centres one window at a time, and an overview that pulls every window back
 * into a grid of tiles so the whole set is visible at once. Mod+G switches
 * between the two; clicking or pressing Enter on a tile returns to the
 * carousel on that window, and a tile whose host made it dismissible can be
 * thrown off the deck.
 *
 * The deck is content-agnostic. Each `WindowDeckPane` is a frame the host
 * composes any Nessa components into — a conversation, a calendar, a board, a
 * photograph, an offer card — and the deck only owns where those frames sit
 * and how they move.
 *
 * Both the focused pane and the mode may be controlled or left to the deck.
 *
 * The deck's scroller is a size query container, which makes it the
 * containing block for `position: fixed` content inside a pane. Content that
 * must escape the deck — a dialog, a menu that outgrows the window — should
 * be rendered into a portal, as the Nessa overlay components already are.
 *
 * @param props - Selection, mode, keymap, sizing, and native container
 * properties.
 * @returns The deck, its scroller, and the panes composed into it.
 */
function WindowDeck({
  activePane,
  defaultActivePane,
  onActivePaneChange,
  mode,
  defaultMode = "carousel",
  onModeChange,
  shortcuts,
  paneWidth = "min(880px, 82cqw)",
  paneHeight = "100%",
  overviewLayout,
  wheelNavigation = true,
  labels: labelsProp,
  className,
  style,
  children,
  ref,
  ...props
}: WindowDeckProps) {
  const [panes, setPanes] = React.useState<RegisteredWindowDeckPane[]>([])
  const [uncontrolledActive, setUncontrolledActive] = React.useState<
    string | undefined
  >(defaultActivePane)
  const [uncontrolledMode, setUncontrolledMode] =
    React.useState<WindowDeckMode>(defaultMode)
  const [tiles, setTiles] = React.useState<Record<string, WindowDeckTile>>({})
  const [settling, setSettling] = React.useState(false)
  // Nonced, so a request that never completed cannot dismiss a later pane
  // that happens to mount under the same id.
  const [dismissRequest, setDismissRequest] = React.useState<
    { paneId: string; nonce: number } | undefined
  >(undefined)
  const dismissNonceRef = React.useRef(0)
  const [announcement, setAnnouncement] = React.useState("")

  const rootRef = React.useRef<HTMLDivElement>(null)
  const viewportRef = React.useRef<HTMLDivElement>(null)
  const railRef = React.useRef<HTMLDivElement>(null)
  const composedRef = React.useMemo(() => composeRefs(rootRef, ref), [ref])
  // The pane the overview should return to when it is dismissed rather than
  // opened onto a specific window. Held as state as well as a ref: the tiles
  // mark it with aria-current, so a render must see the current value, while
  // the handlers need to read and write it synchronously.
  const [restorePaneId, setRestorePaneId] = React.useState<string | undefined>(
    undefined,
  )
  const restoreRef = React.useRef<string | undefined>(undefined)

  /**
   * Records the window the overview returns to.
   *
   * @param paneId - The window to return to, or undefined for none.
   */
  const setRestore = React.useCallback((paneId: string | undefined) => {
    restoreRef.current = paneId
    setRestorePaneId(paneId)
  }, [])
  // The pane a pending settle is landing on, read by the layout effect that
  // performs the scroll jump in the same commit as the carousel styles.
  const pendingSettleRef = React.useRef<string | undefined>(undefined)
  // Finishes a settle that is still running, so a second visit to the
  // overview never measures a rail that is mid-slide.
  const finishSettleRef = React.useRef<(() => void) | null>(null)
  // The mode the last commit rendered, so the settle runs on the transition
  // out of the overview however the host got there.
  // Always starts at the carousel, so a deck that opens in the overview
  // still runs the entry branch below and seeds the window it returns to.
  const previousModeRef = React.useRef<WindowDeckMode>("carousel")
  const scrollFrameRef = React.useRef<number | null>(null)
  // A selection that came from the user's own scrolling must not be answered
  // with a scroll of our own, or the carousel fights the gesture. A scroll
  // the deck itself started must not be read back as a selection at all, or
  // one keypress reports every window it travels past.
  const fromScrollRef = React.useRef(false)
  const programmaticScrollRef = React.useRef(false)
  const scrollTokenRef = React.useRef(0)
  // Whether the deck has already told its host that it has no room for a grid.
  const forcedCarouselRef = React.useRef(false)
  const centeredRef = React.useRef(false)
  // A dismissal a pane has finished playing, waiting to see whether the host
  // actually removes it.
  const pendingRemovalsRef = React.useRef(
    new Map<
      string,
      { wasActive: boolean; neighbour: string | undefined; name: string }
    >(),
  )
  // Retained panes waiting out their grace period, so the timers can be
  // cleared if the deck goes away first.
  const retainedTimersRef = React.useRef(new Map<string, number>())
  const panesRef = React.useRef(panes)
  const activePaneIdRef = React.useRef<string | undefined>(undefined)
  const mountedRef = React.useRef(true)

  panesRef.current = panes

  const labels = React.useMemo<WindowDeckLabels>(
    () => ({ ...windowDeckDefaultLabels, ...labelsProp }),
    [labelsProp],
  )
  const paneIds = React.useMemo(() => panes.map((pane) => pane.id), [panes])
  const resolvedMode = mode ?? uncontrolledMode
  const requestedActive = activePane ?? uncontrolledActive
  const activePaneId =
    requestedActive !== undefined && paneIds.includes(requestedActive)
      ? requestedActive
      : paneIds[0]

  activePaneIdRef.current = activePaneId

  // Read by value, so a host writing `overviewLayout={{ columns: 2 }}` inline
  // does not hand the measurement a new identity on every render.
  const { columns, maxRows, gap, insets, minScale } = overviewLayout ?? {}
  const insetTop = insets?.top
  const insetBottom = insets?.bottom
  const insetHorizontal = insets?.horizontal
  const overviewOptions = React.useMemo<WindowDeckOverviewOptions>(
    () => ({
      columns,
      maxRows,
      gap,
      minScale,
      insets: { top: insetTop, bottom: insetBottom, horizontal: insetHorizontal },
    }),
    [columns, gap, insetBottom, insetHorizontal, insetTop, maxRows, minScale],
  )

  React.useEffect(() => {
    const timers = retainedTimersRef.current

    return () => {
      mountedRef.current = false
      for (const timer of timers.values()) window.clearTimeout(timer)
      timers.clear()
    }
  }, [])

  const paneElement = React.useCallback(
    (paneId: string | undefined) =>
      panesRef.current.find((pane) => pane.id === paneId)?.element,
    [],
  )

  const registerPane = React.useCallback((pane: RegisteredWindowDeckPane) => {
    setPanes((current) =>
      sortByDocumentPosition([
        ...current.filter((entry) => entry.id !== pane.id),
        pane,
      ]),
    )

    return () =>
      setPanes((current) => current.filter((entry) => entry.id !== pane.id))
  }, [])

  const setActive = React.useCallback(
    (paneId: string) => {
      if (activePane === undefined) setUncontrolledActive(paneId)

      const changed = paneId !== activePaneId
      // A host holding an id the deck could not resolve is told even when
      // nothing moved, because the value it holds is the one that is wrong.
      const correctsHost =
        requestedActive !== undefined && paneId !== requestedActive

      if (changed || correctsHost) onActivePaneChange?.(paneId)
    },
    [activePane, activePaneId, onActivePaneChange, requestedActive],
  )

  const setMode = React.useCallback(
    (next: WindowDeckMode) => {
      if (mode === undefined) setUncontrolledMode(next)
      if (next !== resolvedMode) onModeChange?.(next)
    },
    [mode, onModeChange, resolvedMode],
  )

  const centerPane = React.useCallback(
    (paneId: string | undefined, behavior: ScrollBehavior) => {
      const viewport = viewportRef.current
      const pane = paneElement(paneId)

      if (!viewport || !pane) return

      // The scroll the deck starts is not a selection the user made, so the
      // scroll handler stands down until it has finished travelling.
      const target = centeredScrollLeft(viewport, pane)

      // Already there. Scrolling to the current position moves nothing and so
      // may never report that it finished, which would leave scroll-driven
      // selection suppressed for the length of the fallback timer.
      if (Math.abs(viewport.scrollLeft - target) < 1) return

      // The token only ever counts up: a superseded release must be able to
      // tell that it is stale, which a reused number could not express.
      scrollTokenRef.current += 1
      const token = scrollTokenRef.current

      programmaticScrollRef.current = true
      viewport.scrollTo({ left: target, behavior })

      /** Hands scroll-driven selection back once the deck has stopped. */
      const release = () => {
        // Detached first and unconditionally: a superseded release that
        // returned early would leave its listener on the viewport for good.
        viewport.removeEventListener("scrollend", release)
        if (scrollTokenRef.current !== token) return
        programmaticScrollRef.current = false
      }

      viewport.addEventListener("scrollend", release)
      // Not every browser fires scrollend, and an instant scroll may finish
      // before the listener is attached, so a timer closes the window too.
      window.setTimeout(release, behavior === "smooth" ? 700 : 0)
    },
    [paneElement],
  )

  /**
   * Measures the deck and lays every pane out on the overview grid.
   *
   * Measurement is taken from layout geometry rather than from painted
   * rectangles: the carousel already scales the unfocused panes, and a tile
   * transform replaces that scale rather than compounding with it.
   *
   * @returns Whether the deck has room to present an overview at all.
   */
  const measureTiles = React.useCallback(() => {
    const viewport = viewportRef.current
    const current = panesRef.current

    if (!viewport || current.length === 0) return false

    // A close may still be settling. Its rail shift is a transform on the
    // panes' parent, so leaving it in flight would push the whole grid
    // sideways by however far the rail still had to travel. Finishing it now
    // also cancels its timer, which would otherwise fire after this
    // measurement and reset the scroller underneath the tiles.
    finishSettleRef.current?.()

    const rects: WindowDeckRect[] = current.map((pane) => ({
      left: pane.element.offsetLeft - viewport.offsetLeft - viewport.scrollLeft,
      top: pane.element.offsetTop - viewport.offsetTop,
      width: pane.element.offsetWidth,
      height: pane.element.offsetHeight,
    }))
    const placements = computeOverviewTiles(
      rects,
      { width: viewport.clientWidth, height: viewport.clientHeight },
      overviewOptions,
    )

    if (placements === null) return false

    const next = Object.fromEntries(
      current.map((pane, index) => [pane.id, placements[index]]),
    )

    // A resize observer reports the size it starts with, so an unchanged
    // measurement must not churn a new object through every pane.
    setTiles((existing) => (sameTiles(existing, next) ? existing : next))
    return true
  }, [overviewOptions])

  const openOverview = React.useCallback(() => {
    // A deck with no room for a grid stays a carousel: an overview whose
    // tiles cannot fit is one where the panes have not moved, snapping is
    // off, and everything past the fold is unreachable.
    if (!measureTiles()) return
    setMode("overview")
  }, [measureTiles, setMode])

  const closeOverview = React.useCallback(
    (paneId?: string) => {
      const landing = paneId ?? restoreRef.current ?? activePaneId

      if (landing === undefined) {
        setMode("carousel")
        return
      }
      // The jump itself happens in a layout effect keyed on the mode, so a
      // host that drives the mode itself gets the same settle this does.
      pendingSettleRef.current = landing
      setActive(landing)
      setMode("carousel")
    },
    [activePaneId, setActive, setMode],
  )

  const selectPane = React.useCallback(
    (paneId: string) => {
      if (resolvedMode === "overview") {
        closeOverview(paneId)
        return
      }
      fromScrollRef.current = false
      setActive(paneId)
      if (paneId === activePaneId) centerPane(paneId, "smooth")
    },
    [activePaneId, centerPane, closeOverview, resolvedMode, setActive],
  )

  /**
   * Takes a pane's word that it has finished leaving.
   *
   * Nothing is announced or refocused here: `onDismiss` is a request, and a
   * host is free to decline it. The deck acts only once the pane has
   * actually left the deck, which the effect below watches for.
   */
  const reportDismissal = React.useCallback(
    (paneId: string, outcome: "left" | "retained") => {
      setDismissRequest(undefined)

      if (outcome === "retained") {
        // The pane is still mounted, which usually means the host declined.
        // It may equally mean the host is waiting on a confirmation or a
        // request before removing it, and those two are indistinguishable
        // except by time — so the record is kept briefly rather than dropped
        // at once. A removal that lands inside the window is still announced
        // and still rescues focus; after it, the pane is treated as kept and
        // nothing is left behind to fire against an unrelated removal later.
        const timers = retainedTimersRef.current

        window.clearTimeout(timers.get(paneId))
        timers.set(
          paneId,
          window.setTimeout(() => {
            timers.delete(paneId)
            pendingRemovalsRef.current.delete(paneId)
          }, RETAINED_GRACE_MS),
        )
        return
      }

      window.clearTimeout(retainedTimersRef.current.get(paneId))
      retainedTimersRef.current.delete(paneId)

      const current = panesRef.current
      const index = current.findIndex((pane) => pane.id === paneId)

      // Keyed by pane, because two panes thrown in quick succession are both
      // in flight before either removal has committed. Whether the pane was
      // the focused one is recorded now: by the time the removal lands the
      // deck has already fallen back to another window, so asking then would
      // never find it.
      pendingRemovalsRef.current.set(paneId, {
        wasActive: activePaneIdRef.current === paneId,
        neighbour:
          index === -1
            ? undefined
            : (current[index + 1] ?? current[index - 1])?.id,
        name: current[index]?.element.getAttribute("aria-label") ?? paneId,
      })
    },
    [],
  )

  // A pane the host actually removed leaves a hole in the deck: focus was on
  // it, selection may have named it, and the removal is worth announcing.
  React.useEffect(() => {
    const pending = pendingRemovalsRef.current

    if (pending.size === 0) return

    const removed: { neighbour: string | undefined; name: string }[] = []

    for (const [paneId, removal] of pending) {
      if (paneIds.includes(paneId)) continue
      pending.delete(paneId)
      removed.push(removal)

      const neighbour =
        removal.neighbour !== undefined && paneIds.includes(removal.neighbour)
          ? removal.neighbour
          : undefined

      if (restoreRef.current === paneId) setRestore(neighbour)
      if (removal.wasActive && neighbour !== undefined) setActive(neighbour)
    }

    if (removed.length === 0) return
    // Every window that left is named: two thrown in quick succession are
    // one commit apart, and reporting only the last would lose the other.
    setAnnouncement(
      removed.map((entry) => labels.paneDismissed(entry.name)).join(", "),
    )

    // Focus is only rescued when the removal actually dropped it out of the
    // deck: a host that moved focus somewhere of its own must keep it.
    const root = rootRef.current

    if (root === null) return
    if (root.contains(root.ownerDocument.activeElement)) return

    const neighbour = removed[0].neighbour
      ? paneElement(removed[0].neighbour)
      : undefined

    // The deck itself is the last resort, so the keyboard never lands back
    // at the top of the document because the deck emptied.
    ;(neighbour ?? root).focus()
  }, [activePaneId, labels, paneElement, paneIds, setActive, setRestore])

  /**
   * Returns the deck from the overview without a visible seam.
   *
   * The scroller is jumped to the landing pane and the rail is shifted by the
   * same distance in the same frame, so the composite is pixel-identical and
   * nothing flashes. The rail then transitions its shift away on the same
   * curve the panes use to leave their tiles, which reads as one movement.
   */
  React.useLayoutEffect(() => {
    const previous = previousModeRef.current
    previousModeRef.current = resolvedMode

    if (resolvedMode === "overview") {
      // Whichever route opened the overview, the window the deck came from
      // is the one a dismissal returns to.
      if (previous !== "overview") setRestore(activePaneId)
      // The deck is in the overview, so any close that was requested did not
      // happen; a landing left armed here would settle a later close onto
      // the wrong window.
      pendingSettleRef.current = undefined
      return
    }
    if (previous !== "overview") return

    const landing = pendingSettleRef.current ?? activePaneId
    pendingSettleRef.current = undefined

    const viewport = viewportRef.current
    const rail = railRef.current
    const pane = paneElement(landing)

    if (!viewport || !rail || !pane) return

    const before = viewport.scrollLeft
    // Both of the scroller's carousel behaviours have to be off before the
    // jump, and a class cannot do it: this effect runs in the commit that
    // restored them, and turning them off through state would land a frame
    // too late.
    //
    // Smooth scrolling would make the write below an animation that reads
    // back the position it has not left yet, so the shift would compute to
    // zero and the seam this mechanism exists to hide is what the user sees.
    // Snapping is worse: snap areas are measured from transformed boxes, so
    // shifting the rail moves every snap position with it and the browser
    // re-snaps at once, landing the deck a whole window along.
    viewport.style.scrollBehavior = "auto"
    viewport.style.scrollSnapType = "none"
    // The shift is written with transitions suppressed; only its removal is
    // allowed to animate.
    rail.style.transitionProperty = "none"
    viewport.scrollLeft = centeredScrollLeft(viewport, pane)
    const settled = viewport.scrollLeft
    rail.style.translate = `${settled - before}px`
    // Reading layout is the flush: it forces the shift to be computed, so the
    // line below has a value to transition from.
    void rail.getBoundingClientRect()
    rail.style.removeProperty("transition-property")
    rail.style.translate = "0px"

    const duration = longestTransitionMs(pane)
    let timer: number | undefined

    /**
     * Ends the settle when the rail's own slide finishes, ignoring the
     * transitions of everything inside it.
     *
     * @param event - The transition that ended.
     */
    const onRailSettled = (event: TransitionEvent) => {
      if (event.target !== rail || event.propertyName !== "translate") return
      finish()
    }

    /** Hands the scroller back its snapping once nothing is transformed. */
    const finish = () => {
      if (timer !== undefined) window.clearTimeout(timer)
      rail.removeEventListener("transitionend", onRailSettled)
      finishSettleRef.current = null
      rail.style.removeProperty("translate")
      rail.style.removeProperty("transition-property")
      viewport.style.removeProperty("scroll-behavior")
      viewport.style.removeProperty("scroll-snap-type")
      // Snap areas are computed from transformed boxes; re-enabling snap
      // before the panes are untransformed makes the browser jump to a
      // neighbour. Restoring the offset keeps that handover invisible.
      viewport.scrollLeft = settled
      // Skipped only for a real unmount. This cleanup also runs on an
      // ordinary dependency change — a controlled host answering the close
      // with a later commit is enough — and skipping the write there would
      // latch the deck settling: non-interactive, unscrollable, and with no
      // other writer able to clear it.
      if (mountedRef.current) setSettling(false)
    }

    if (duration === 0) {
      finish()
      return
    }

    setSettling(true)
    finishSettleRef.current = finish
    // The rail's own movement is what the settle is waiting on, so it ends
    // the settle; the timer is only a backstop for the cases a transition
    // never reports — a hidden tab, an interrupted animation. Its margin is
    // generous on purpose: finishing early re-enables snapping while the
    // panes are still transformed, and the browser then snaps to a box that
    // is still moving, which is a visible jump at the end of the return.
    rail.addEventListener("transitionend", onRailSettled)
    timer = window.setTimeout(finish, duration + 200)

    // An unmount, or another mode change, must not strand the rail at its
    // shift: the settle is finished outright rather than merely abandoned.
    return () => {
      if (finishSettleRef.current === finish) finish()
    }
  }, [activePaneId, paneElement, resolvedMode, setRestore])



  // Panes register on mount, so a host that reorders them without changing
  // the set would otherwise keep the order they first mounted in — which is
  // the order the overview tiles them in and the arrows walk through.
  React.useLayoutEffect(() => {
    setPanes((current) => {
      // Checked in one pass before anything is allocated: this runs on every
      // commit, including the ones a scroll produces.
      const ordered = current.every(
        (pane, index) =>
          index === 0 ||
          (current[index - 1].element.compareDocumentPosition(pane.element) &
            Node.DOCUMENT_POSITION_FOLLOWING) !==
            0,
      )

      return ordered ? current : sortByDocumentPosition(current)
    })
  })

  // A pane the host removed on its own leaves the uncontrolled selection
  // naming a window that is gone. Left alone, selection would snap back to
  // it if a pane ever mounted under that id again.
  React.useEffect(() => {
    if (activePane !== undefined || uncontrolledActive === undefined) return
    if (paneIds.length === 0 || paneIds.includes(uncontrolledActive)) return
    // Functional, so a selection a dismissal has already queued wins: that
    // one names the neighbour of the window that left, which is where the
    // user was, and this one only exists to unstick a dead id.
    setUncontrolledActive((current) =>
      current !== undefined && paneIds.includes(current) ? current : activePaneId,
    )
  }, [activePane, activePaneId, paneIds, uncontrolledActive])

  // A host holding an id the deck no longer has is told, rather than left to
  // discover that the deck quietly moved on without it.

  // Every route into the overview lands here — the shortcut, a host driving
  // the mode itself, a pane leaving the grid — so the tiles are laid out
  // before the frame is painted whichever way it opened. `panes` in the deps
  // is what re-tiles the grid over the gap a dismissal leaves.
  React.useLayoutEffect(() => {
    if (resolvedMode !== "overview") return
    // A host may put the deck into the overview itself, so the guard that
    // keeps an unreadable grid off the screen lives here rather than only in
    // the shortcut: without it the panes sit untransformed in a scroller
    // that no longer scrolls, and everything past the fold is unreachable.
    if (measureTiles()) {
      forcedCarouselRef.current = false
      // A deck that opened straight into the overview has no earlier
      // carousel commit to have seeded the window it returns to.
      if (restoreRef.current === undefined && activePaneId !== undefined) {
        setRestore(activePaneId)
      }
      return
    }
    if (panes.length === 0 || forcedCarouselRef.current) return
    // Latched, so a host that answers onModeChange by re-rendering without
    // changing the mode is asked once rather than on every render it causes.
    forcedCarouselRef.current = true
    setMode("carousel")
  }, [activePaneId, measureTiles, panes, resolvedMode, setMode, setRestore])

  React.useEffect(() => {
    if (requestedActive === undefined || activePaneId === undefined) return
    if (requestedActive === activePaneId || !paneIds.length) return
    onActivePaneChange?.(activePaneId)
  }, [activePaneId, onActivePaneChange, paneIds.length, requestedActive])

  // Announced on the mode's own change, not on every render that follows
  // it — but a deck whose panes have not registered yet has nothing true to
  // say, so the announcement waits for them rather than reporting an empty
  // overview it will never correct.
  const announcedRef = React.useRef<string | undefined>(undefined)

  React.useEffect(() => {
    if (paneIds.length === 0) return

    const signature = `${resolvedMode}:${paneIds.length}`

    if (announcedRef.current === signature) return
    const wasAnnounced = announcedRef.current

    announcedRef.current = signature
    // Nothing has changed yet on the first pass: a deck must not narrate
    // itself into the live region simply for being on the page.
    if (wasAnnounced === undefined) return
    // Only the mode's own change is announced. A changing pane count while
    // the overview stays open is a dismissal, which announces itself.
    if (wasAnnounced?.split(":")[0] === resolvedMode) return

    setAnnouncement(
      resolvedMode === "overview"
        ? labels.overviewOpened(paneIds.length)
        : activePaneId === undefined
          ? ""
          : labels.overviewClosed(
              paneElement(activePaneId)?.getAttribute("aria-label") ??
                activePaneId,
            ),
    )
  }, [activePaneId, labels, paneElement, paneIds.length, resolvedMode])

  // The opening view is centred without animation: there is no previous
  // position for the deck to have travelled from.
  React.useLayoutEffect(() => {
    if (centeredRef.current || panes.length === 0) return
    centeredRef.current = true
    centerPane(activePaneId, "instant")
  }, [activePaneId, centerPane, panes.length])

  // A selection made anywhere but the scroller — a shortcut, a tile, the
  // host — brings its pane to the middle.
  React.useEffect(() => {
    if (resolvedMode !== "carousel" || settling) return
    if (fromScrollRef.current) {
      fromScrollRef.current = false
      return
    }
    if (!centeredRef.current) return

    centerPane(
      activePaneId,
      window.matchMedia(reducedMotionQuery).matches ? "instant" : "smooth",
    )
  }, [activePaneId, centerPane, resolvedMode, settling])

  // The overview is measured from the deck's own box, so a host that resizes
  // it — a window resize, a sidebar opening — re-tiles rather than leaving
  // the grid laid out for the old size.
  React.useEffect(() => {
    const viewport = viewportRef.current

    if (resolvedMode !== "overview" || !viewport) return

    const observer = new ResizeObserver(() => {
      if (measureTiles()) forcedCarouselRef.current = false
    })
    observer.observe(viewport)

    return () => observer.disconnect()
  }, [measureTiles, resolvedMode])

  React.useEffect(
    () => () => {
      if (scrollFrameRef.current !== null) {
        cancelAnimationFrame(scrollFrameRef.current)
      }
    },
    [],
  )

  // The keymap and everything the handler reads live in a ref, so the window
  // listener is attached once rather than re-attached on every render — a
  // host writing `shortcuts={{ ... }}` inline would otherwise tear the
  // listener down and rebuild it on every scroll frame.
  const keymap = resolveWindowDeckShortcuts(shortcuts)
  const handleKeyDownRef = React.useRef<(event: KeyboardEvent) => void>(
    () => {},
  )

  handleKeyDownRef.current = (event: KeyboardEvent) => {
    if (event.defaultPrevented || event.repeat || event.isComposing) return
    if (handledShortcutEvents.has(event)) return

    // Only this deck's own keystrokes count, so two decks on one page never
    // fight over a shortcut. When nothing is focused the first deck takes it,
    // as the user is addressing the page.
    const root = rootRef.current
    const target = event.target
    const insideDeck =
      root !== null && target instanceof Node && root.contains(target)
    const nothingFocused =
      !(target instanceof HTMLElement) ||
      target === target.ownerDocument.body ||
      target === target.ownerDocument.documentElement

    if (!insideDeck && !nothingFocused) return

    /** Claims the event so no other handler answers the same keystroke. */
    const claim = (preventDefault: boolean | undefined) => {
      handledShortcutEvents.add(event)
      if (preventDefault !== false) event.preventDefault()
    }

    // Escape leaves the overview whatever the keymap says: it is the
    // dismissal every layered view in the system answers to.
    if (event.key === "Escape" && resolvedMode === "overview") {
      claim(true)
      closeOverview()
      return
    }

    if (keymap === false) return

    if (matchesWindowDeckShortcut(event, keymap.toggleOverview)) {
      claim(
        keymap.toggleOverview === false
          ? undefined
          : keymap.toggleOverview.preventDefault,
      )
      if (resolvedMode === "overview") closeOverview()
      else openOverview()
      return
    }

    if (
      resolvedMode === "overview" &&
      matchesWindowDeckShortcut(event, keymap.dismissPane)
    ) {
      // The tile the user is on, not the one the deck happens to have
      // focused: in the overview every tile is a focus stop, and destroying
      // a different window than the one under the cursor is unrecoverable.
      const focused = panesRef.current.find(
        (pane) =>
          target instanceof Node &&
          (pane.element === target || pane.element.contains(target)),
      )
      const pane = focused ?? panesRef.current.find((p) => p.id === activePaneId)

      if (pane?.element.hasAttribute("data-dismissible")) {
        claim(
          keymap.dismissPane === false
            ? undefined
            : keymap.dismissPane.preventDefault,
        )
        dismissNonceRef.current += 1
        setDismissRequest({ paneId: pane.id, nonce: dismissNonceRef.current })
        return
      }
    }

    const step = matchesWindowDeckShortcut(event, keymap.nextPane)
      ? 1
      : matchesWindowDeckShortcut(event, keymap.previousPane)
        ? -1
        : 0

    if (step === 0) return

    const shortcut = step === 1 ? keymap.nextPane : keymap.previousPane
    claim(shortcut === false ? undefined : shortcut.preventDefault)

    const index = paneIds.indexOf(activePaneId ?? "")
    const next = paneIds[Math.min(Math.max(index + step, 0), paneIds.length - 1)]

    if (next === undefined) return
    // In the overview the shortcut moves the tile the user is on, so the
    // keyboard and the pointer address the same set of targets.
    if (resolvedMode === "overview") paneElement(next)?.focus()
    fromScrollRef.current = false
    setActive(next)
  }

  React.useEffect(() => {
    /** Delegates to the current handler, which every render refreshes. */
    const listener = (event: KeyboardEvent) => handleKeyDownRef.current(event)

    window.addEventListener("keydown", listener)
    return () => window.removeEventListener("keydown", listener)
  }, [])

  /** Follows the scroller, so the centred window is the focused one. */
  const handleScroll = () => {
    const viewport = viewportRef.current

    if (
      resolvedMode !== "carousel" ||
      settling ||
      programmaticScrollRef.current ||
      !viewport ||
      scrollFrameRef.current !== null
    ) {
      return
    }

    scrollFrameRef.current = requestAnimationFrame(() => {
      scrollFrameRef.current = null

      const centre = viewport.scrollLeft + viewport.clientWidth / 2
      const closest = panesRef.current.reduce<{ id?: string; distance: number }>(
        (best, pane) => {
          const distance = Math.abs(
            pane.element.offsetLeft -
              viewport.offsetLeft +
              pane.element.offsetWidth / 2 -
              centre,
          )

          return distance < best.distance ? { id: pane.id, distance } : best
        },
        { distance: Number.POSITIVE_INFINITY },
      )

      if (closest.id === undefined || closest.id === activePaneId) return
      fromScrollRef.current = true
      setActive(closest.id)
    })
  }

  const contextValue = React.useMemo(
    () => ({
      activePaneId,
      dismissRequest,
      mode: resolvedMode,
      paneIds,
      registerPane,
      reportDismissal,
      restorePaneId,
      selectPane,
      settling,
      tileFor: (paneId: string) => tiles[paneId],
    }),
    [
      activePaneId,
      dismissRequest,
      paneIds,
      registerPane,
      reportDismissal,
      resolvedMode,
      restorePaneId,
      selectPane,
      settling,
      tiles,
    ],
  )

  return (
    <WindowDeckContext.Provider value={contextValue}>
      <div
        {...props}
        ref={composedRef}
        data-slot="window-deck"
        data-mode={resolvedMode}
        // Focusable only as the landing place for focus a dismissal
        // dropped; it is not a tab stop of its own.
        tabIndex={-1}
        style={
          {
            ...style,
            "--nessa-window-deck-pane-width": paneWidth,
            "--nessa-window-deck-pane-height": paneHeight,
          } as React.CSSProperties
        }
        className={cn("relative isolate h-full w-full", className)}
      >
        <div
          ref={viewportRef}
          data-slot="window-deck-viewport"
          data-settling={settling ? "" : undefined}
          onScroll={handleScroll}
          onWheel={(event) => {
            const viewport = viewportRef.current

            if (
              !wheelNavigation ||
              resolvedMode !== "carousel" ||
              settling ||
              !viewport ||
              Math.abs(event.deltaY) <= Math.abs(event.deltaX) ||
              hasScrollableAncestor(event.target, viewport)
            ) {
              return
            }

            // Explicitly instant: the scroller carries `scroll-smooth` for
            // its own centring, and a wheel tick that animated would read
            // back a mid-flight position and under-travel on the next one.
            viewport.scrollBy({ left: event.deltaY, behavior: "instant" })
          }}
          className={cn(
            "h-full w-full overflow-y-hidden [scrollbar-width:none] [&::-webkit-scrollbar]:hidden",
            // The carousel is a snapping scroller. The overview stops
            // scrolling entirely: every window is on screen, and a snap
            // computed from tile transforms would drag the deck sideways.
            // A container, so the end spacers can be sized against the deck's
            // own width rather than against the rail's intrinsic one.
            "@container",
            resolvedMode === "carousel"
              ? "snap-x snap-mandatory overflow-x-auto scroll-smooth motion-reduce:scroll-auto"
              : "overflow-x-hidden [scroll-snap-type:none]",
            settling && "overflow-x-hidden scroll-auto [scroll-snap-type:none]",
          )}
        >
          <div
            ref={railRef}
            data-slot="window-deck-rail"
            // The rail rides the same curve and duration as the panes: the
            // two are one movement, and any difference between them shows up
            // as the seam the settle exists to hide.
            className="flex h-full w-max items-center gap-6 py-6 transition-[translate] [transition-duration:calc(var(--nessa-motion-duration-slow)*1.5)] [transition-timing-function:var(--nessa-motion-easing-standard)] [will-change:transform] motion-reduce:transition-none motion-reduce:[will-change:auto]"
          >
            {/*
              Real items rather than padding on the rail: a scroll container
              does not extend its scrollable range to cover a flex
              container's trailing padding, which leaves the last pane a
              half-viewport short of the middle and the settle unable to
              centre it. Sized in container units so the measurement is the
              deck's width, not the rail's own intrinsic width.
            */}
            <div
              aria-hidden="true"
              data-slot="window-deck-rail-spacer"
              className="w-[max(1rem,calc((100cqw-var(--nessa-window-deck-pane-width))/2))] shrink-0 self-stretch"
            />
            {children}
            <div
              aria-hidden="true"
              data-slot="window-deck-rail-spacer"
              className="w-[max(1rem,calc((100cqw-var(--nessa-window-deck-pane-width))/2))] shrink-0 self-stretch"
            />
          </div>
        </div>
        <div
          aria-live="polite"
          aria-atomic="true"
          data-slot="window-deck-announcement"
          className="sr-only"
        >
          {announcement}
        </div>
      </div>
    </WindowDeckContext.Provider>
  )
}

export {
  WindowDeck,
  windowDeckDefaultLabels,
  type WindowDeckLabels,
  type WindowDeckProps,
}

"use client"

/** @responsibility Renders one window of a WindowDeck: its chrome, its host-supplied content, its behaviour as an overview tile, and the throw that dismisses it. */

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  composeRefs,
  useWindowDeck,
  type WindowDeckDismissDirection,
  type WindowDeckDismissal,
} from "./window-deck-context"
import { longestTransitionMs } from "./window-deck-motion"

/** How far a pane must travel before releasing it dismisses it, in pixels. */
const DISMISS_DISTANCE = 72

/** Speed that dismisses a pane regardless of distance, in pixels per ms. */
const DISMISS_VELOCITY = 0.5

/** How much of a drag against the allowed directions is shown, as a ratio. */
const RUBBER_BAND = 0.18

/** How far a gesture must travel before it stops being a tap. */
const ENGAGE_DISTANCE = 8

/** The default throw: up and out, as a window is dismissed from an overview. */
const DEFAULT_DIRECTIONS: readonly WindowDeckDismissDirection[] = ["up"]

/** Properties accepted by one WindowDeck pane. */
interface WindowDeckPaneProps
  extends Omit<React.ComponentProps<"div">, "id" | "title" | "onDismiss"> {
  /**
   * Unique id of the pane within its deck. Keys selection and is rendered as
   * the element id.
   */
  id: string
  /**
   * The pane's accessible name. It names the pane's group in the carousel
   * and its tile in the overview, so give it the name of the window rather
   * than a description of its content.
   */
  label: string
  /** Chrome across the top of the window, above its content. */
  header?: React.ReactNode
  /** Chrome across the bottom of the window, below its content. */
  footer?: React.ReactNode
  /**
   * Whether the pane's content scrolls on its own. Turn it off when the
   * content fills the pane or manages its own scrolling, as a photograph, a
   * message list, or a canvas does.
   * @defaultValue true
   */
  scrollable?: boolean
  /**
   * Whether the pane draws a window surface — border, background, and
   * shadow. Turn it off for content that should reach the pane's edges, such
   * as a photograph.
   * @defaultValue true
   */
  chrome?: boolean
  /** Classes for the header slot, for chrome the window frame should not dictate. */
  headerClassName?: string
  /** Classes for the content slot. */
  contentClassName?: string
  /** Classes for the footer slot. */
  footerClassName?: string
  /**
   * Whether the user may throw this pane away. Defaults to true once
   * `onDismiss` is supplied, so a pinned pane in a dismissible deck sets it
   * to false explicitly.
   * @defaultValue true when onDismiss is given
   */
  dismissible?: boolean
  /**
   * The edges this pane may be thrown towards. A drag in any other direction
   * rubber-bands and springs back, and the deck's dismiss shortcut reports
   * the first direction listed.
   * @defaultValue ["up"]
   */
  dismissDirections?: readonly WindowDeckDismissDirection[]
  /**
   * Called once the pane has finished leaving, with the direction it went,
   * whether it was thrown or dismissed from the keyboard, and how far and
   * fast it travelled. The host removes the pane from its own data; the deck
   * re-tiles the rest around the gap. A host that declines to remove it gets
   * the pane back where it was.
   */
  onDismiss?: (dismissal: WindowDeckDismissal) => void
}

/** A dismissal gesture in progress. */
interface DragState {
  /** The pointer driving it. */
  pointerId: number
  /** Where it started, in client coordinates. */
  originX: number
  originY: number
  /** When it started, for the fling velocity. */
  startedAt: number
  /** The offset last seen, in pixels. */
  offsetX: number
  offsetY: number
  /** Its speed at the last sample, in pixels per millisecond. */
  velocity: number
  /** Whether the gesture has committed to being a drag rather than a tap. */
  engaged: boolean
}

/** How far, and which way, a released gesture travelled. */
interface Throw {
  direction: WindowDeckDismissDirection
  distance: number
  velocity: number
}

/**
 * Reads a released gesture as a throw towards one of the allowed edges.
 *
 * @param drag - The gesture at the moment of release.
 * @param directions - The edges this pane may be thrown towards.
 * @returns The throw, or undefined when the gesture was not one.
 */
function readThrow(
  drag: DragState,
  directions: readonly WindowDeckDismissDirection[],
): Throw | undefined {
  const candidates: { direction: WindowDeckDismissDirection; distance: number }[] =
    [
      { direction: "up", distance: -drag.offsetY },
      { direction: "down", distance: drag.offsetY },
      { direction: "left", distance: -drag.offsetX },
      { direction: "right", distance: drag.offsetX },
    ]
  const best = candidates
    .filter((candidate) => directions.includes(candidate.direction))
    .reduce<{ direction: WindowDeckDismissDirection; distance: number } | undefined>(
      (winner, candidate) =>
        winner === undefined || candidate.distance > winner.distance
          ? candidate
          : winner,
      undefined,
    )

  if (best === undefined || best.distance <= 0) return undefined

  // A short flick counts as much as a long drag: the gesture is a throw, and
  // requiring the full distance would make a fast one feel ignored.
  const flung =
    best.distance > DISMISS_DISTANCE * 0.4 && drag.velocity >= DISMISS_VELOCITY

  if (best.distance < DISMISS_DISTANCE && !flung) return undefined

  return { ...best, velocity: drag.velocity }
}

/**
 * Renders one window in a WindowDeck. The pane holds no layout state of its
 * own: the deck decides where it sits, how it is scaled, and whether it is
 * currently a tile or the focused window.
 *
 * Its content is whatever the host composes into it — a conversation, a
 * calendar, a board, a photograph, an offer card — and the pane supplies the
 * frame, the optional header and footer chrome, the tile behaviour, and the
 * throw that dismisses it.
 *
 * @param props - The pane id and accessible name, its chrome, its dismissal
 * contract, and native container properties.
 * @returns One window of the deck.
 */
function WindowDeckPane({
  id,
  label,
  header,
  footer,
  scrollable = true,
  chrome = true,
  headerClassName,
  contentClassName,
  footerClassName,
  dismissible = true,
  dismissDirections = DEFAULT_DIRECTIONS,
  onDismiss,
  className,
  style,
  children,
  ref,
  ...props
}: WindowDeckPaneProps) {
  const {
    activePaneId,
    dismissRequest,
    mode,
    registerPane,
    reportDismissal,
    restorePaneId,
    selectPane,
    settling,
    tileFor,
  } = useWindowDeck()
  const elementRef = React.useRef<HTMLDivElement>(null)
  // Memoized so React does not detach and re-attach refs on every render.
  const composedRef = React.useMemo(() => composeRefs(elementRef, ref), [ref])
  const [offset, setOffset] = React.useState({ x: 0, y: 0 })
  const [dragging, setDragging] = React.useState(false)
  const [leaving, setLeaving] = React.useState(false)
  const [retained, setRetained] = React.useState(0)

  const overview = mode === "overview"
  const active = activePaneId === id
  const tile = overview ? tileFor(id) : undefined
  const throwable = dismissible && onDismiss !== undefined && overview

  React.useLayoutEffect(() => {
    const element = elementRef.current

    if (!element) return

    return registerPane({ id, element })
  }, [id, registerPane])

  // Everything the exit needs is read through refs: the listeners are
  // attached once per gesture and must not be rebuilt when the host
  // re-renders, and the exit outlives the commit that started it.
  // A throw ends in a click on the tile it started on. That click must not
  // also open the pane the user just threw away.
  const suppressClickRef = React.useRef(false)
  const dismissalRef = React.useRef<WindowDeckDismissal | null>(null)
  const latchedRef = React.useRef(false)
  const onDismissRef = React.useRef(onDismiss)
  const reportRef = React.useRef(reportDismissal)
  const directionsRef = React.useRef(dismissDirections)

  React.useEffect(() => {
    onDismissRef.current = onDismiss
    reportRef.current = reportDismissal
    directionsRef.current = dismissDirections
  })

  /**
   * Hands the host the dismissal exactly once, then restores the pane.
   *
   * The restore matters for a host that declines the removal — an undo, a
   * confirmation, a failed request: the pane must come back where it was
   * rather than sit invisible in the grid forever.
   */
  const completeDismissal = React.useCallback(() => {
    const dismissal = dismissalRef.current

    if (!dismissal || latchedRef.current) return
    latchedRef.current = true
    dismissalRef.current = null

    onDismissRef.current?.(dismissal)
    reportRef.current(dismissal.paneId, "left")
    // The click that ends a throw never arrives once the pane is playing its
    // exit, so the guard is cleared here rather than waiting for one.
    suppressClickRef.current = false
    setLeaving(false)
    setOffset({ x: 0, y: 0 })
    setRetained((current) => current + 1)
    latchedRef.current = false
  }, [])

  // Reached only if the pane is still mounted after the host was handed the
  // dismissal, which is exactly the case where the host declined it. A host
  // that removed the pane never runs this.
  React.useEffect(() => {
    if (retained === 0) return
    reportRef.current(id, "retained")
  }, [id, retained])

  /**
   * Plays the pane off the deck and hands the host the dismissal when it
   * lands.
   *
   * The landing is timed from the transition the element actually runs, so a
   * theme or a host that turns motion off completes the dismissal at once
   * instead of waiting for a `transitionend` that never fires.
   */
  const dismiss = React.useCallback(
    (dismissal: WindowDeckDismissal) => {
      const element = elementRef.current

      if (!element || dismissalRef.current) return
      dismissalRef.current = dismissal

      const box = element.getBoundingClientRect()
      const away = {
        up: { x: 0, y: -(box.bottom + box.height) },
        down: { x: 0, y: window.innerHeight - box.top + box.height },
        left: { x: -(box.right + box.width), y: 0 },
        right: { x: window.innerWidth - box.left + box.width, y: 0 },
      }[dismissal.direction]

      setDragging(false)
      setLeaving(true)
      setOffset(away)

      const duration = longestTransitionMs(element)

      if (duration === 0) {
        completeDismissal()
        return
      }
      window.setTimeout(completeDismissal, duration + 50)
    },
    [completeDismissal],
  )

  // The deck asks for a dismissal when the keyboard is used, so a thrown
  // pane and a dismissed one leave along the same path.
  const handledRequestRef = React.useRef(0)

  React.useEffect(() => {
    if (dismissRequest?.paneId !== id) return
    // Each request is answered once. A pane remounting under an id whose
    // request was never completed must not dismiss itself on sight.
    if (handledRequestRef.current >= dismissRequest.nonce) return
    handledRequestRef.current = dismissRequest.nonce
    if (!dismissible || !onDismissRef.current) return

    dismiss({
      paneId: id,
      direction: directionsRef.current[0] ?? "up",
      reason: "shortcut",
      distance: 0,
      velocity: 0,
    })
  }, [dismiss, dismissRequest, dismissible, id])

  /**
   * Opens this pane. In the overview that returns the deck to the carousel
   * on this window; in the carousel it centres this window.
   */
  const open = () => selectPane(id)

  // The gesture is tracked on the window rather than on the pane: a throw
  // routinely leaves the tile it started on, and a pointer released outside
  // it must still end the drag rather than strand the pane in mid-air.
  const endDragRef = React.useRef<(() => void) | null>(null)

  React.useEffect(() => () => endDragRef.current?.(), [])

  const handlePointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    props.onPointerDown?.(event)
    if (!throwable || leaving || event.defaultPrevented) return
    // A second finger must not restart the drag the first one is running,
    // which would snap the pane back under the user's hand.
    if (endDragRef.current) return
    if (event.pointerType === "mouse" && event.button !== 0) return

    suppressClickRef.current = false

    const drag: DragState = {
      pointerId: event.pointerId,
      originX: event.clientX,
      originY: event.clientY,
      startedAt: event.timeStamp,
      offsetX: 0,
      offsetY: 0,
      velocity: 0,
      engaged: false,
    }

    /** Detaches the gesture's listeners and forgets it. */
    const stop = () => {
      window.removeEventListener("pointermove", move)
      window.removeEventListener("pointerup", finish)
      window.removeEventListener("pointercancel", cancel)
      endDragRef.current = null
    }

    /** Springs the pane back to where the deck put it. */
    const release = () => {
      stop()
      setDragging(false)
      setOffset({ x: 0, y: 0 })
    }

    /** Tracks the pointer once the gesture has committed to being a drag. */
    const move = (native: PointerEvent) => {
      if (native.pointerId !== drag.pointerId) return

      const deltaX = native.clientX - drag.originX
      const deltaY = native.clientY - drag.originY

      if (!drag.engaged) {
        if (Math.hypot(deltaX, deltaY) < ENGAGE_DISTANCE) return
        drag.engaged = true
        suppressClickRef.current = true
        setDragging(true)
      }

      const directions = directionsRef.current
      const elapsed = Math.max(1, native.timeStamp - drag.startedAt)

      drag.offsetX = deltaX
      drag.offsetY = deltaY
      drag.velocity = Math.hypot(deltaX, deltaY) / elapsed

      // Travel towards an edge the pane can leave by is followed exactly;
      // travel any other way is rubber-banded, so the pane still answers the
      // hand without promising a dismissal it will not perform.
      const follow = (
        distance: number,
        towards: WindowDeckDismissDirection,
        away: WindowDeckDismissDirection,
      ) => {
        const allowed = distance < 0 ? towards : away

        return directions.includes(allowed) ? distance : distance * RUBBER_BAND
      }

      setOffset({
        x: follow(deltaX, "left", "right"),
        y: follow(deltaY, "up", "down"),
      })
    }

    /** Settles the gesture: a throw dismisses, anything else springs back. */
    const finish = (native: PointerEvent) => {
      if (native.pointerId !== drag.pointerId) return
      stop()
      if (!drag.engaged) {
        suppressClickRef.current = false
        return
      }

      const thrown = readThrow(drag, directionsRef.current)

      if (!thrown) {
        setDragging(false)
        setOffset({ x: 0, y: 0 })
        return
      }
      dismiss({ paneId: id, reason: "gesture", ...thrown })
    }

    /** Abandons the gesture when the platform takes the pointer away. */
    const cancel = (native: PointerEvent) => {
      if (native.pointerId !== drag.pointerId) return
      release()
    }

    endDragRef.current = release
    window.addEventListener("pointermove", move)
    window.addEventListener("pointerup", finish)
    window.addEventListener("pointercancel", cancel)
  }

  // The pane's content is never in the tab order unless the user is looking
  // at it: in the overview every window is a tile, and in the carousel the
  // windows either side are scenery.
  const contentInert = overview || !active
  // A pane the user can open is a control in its own right, and must be
  // reachable and operable from the keyboard rather than by pointer alone.
  const openable = overview || !active

  const moved = offset.x !== 0 || offset.y !== 0
  const transform =
    tile || moved
      ? {
          translate: `${(tile?.x ?? 0) + offset.x}px ${(tile?.y ?? 0) + offset.y}px`,
          ...(tile ? { scale: `${tile.scale}` } : {}),
        }
      : undefined

  return (
    // Consumer props spread first so the attributes the pane owns (id, slot,
    // transform, ref, and its gesture and tile behaviour) always win.
    <div
      {...props}
      ref={composedRef}
      id={id}
      data-slot="window-deck-pane"
      data-active={active ? "" : undefined}
      data-mode={mode}
      data-dragging={dragging ? "" : undefined}
      data-leaving={leaving ? "" : undefined}
      data-dismissible={
        dismissible && onDismiss !== undefined ? "" : undefined
      }
      role={openable ? "button" : "group"}
      tabIndex={openable ? 0 : undefined}
      aria-label={label}
      // In the overview the deck marks the window Escape returns to; in the
      // carousel it marks the window the deck is centred on. Either way the
      // state is carried semantically, not by opacity alone.
      aria-current={
        overview
          ? restorePaneId === id
            ? "true"
            : undefined
          : active
            ? "true"
            : undefined
      }
      onClick={(event) => {
        props.onClick?.(event)
        if (event.defaultPrevented) return
        if (suppressClickRef.current) {
          suppressClickRef.current = false
          return
        }
        if (openable) open()
      }}
      onKeyDown={(event) => {
        props.onKeyDown?.(event)
        if (event.defaultPrevented) return
        if (openable && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault()
          open()
          return
        }
        // Delete on a focused tile removes it, so the dismissal is on the
        // pane the user is actually on rather than on whichever one the deck
        // happens to have focused.
        if (!overview || !throwable) return
        if (event.key !== "Backspace" && event.key !== "Delete") return
        // Unmodified only. A chord such as Mod+Backspace is the deck's to
        // interpret, and swallowing it here would leave two bindings for one
        // action that disagree about which pane they act on.
        if (event.metaKey || event.ctrlKey || event.altKey || event.shiftKey) {
          return
        }
        event.preventDefault()
        dismiss({
          paneId: id,
          direction: dismissDirections[0] ?? "up",
          reason: "shortcut",
          distance: 0,
          velocity: 0,
        })
      }}
      onPointerDown={handlePointerDown}
      style={transform ? { ...style, ...transform } : style}
      className={cn(
        "relative flex w-(--nessa-window-deck-pane-width) flex-none snap-center flex-col overflow-hidden outline-none",
        "h-(--nessa-window-deck-pane-height)",
        chrome &&
          "rounded-xl border border-border bg-card text-card-foreground shadow-lg",
        // Everything the deck moves is a transform, so a pane never reflows
        // its content while it travels between carousel, tile, and off-deck.
        //
        // The curve is the standard one rather than the emphasized one, and
        // the duration is half again the slow token: a window leaves at once
        // and coasts into place, which is how a spring of the weight this
        // movement wants behaves. Easing in at the start — which is what the
        // emphasized curve does — reads as the deck hesitating. Both stay
        // derived from the motion tokens, so reduced motion still zeroes them.
        "origin-center transition-[translate,scale,opacity] [transition-duration:calc(var(--nessa-motion-duration-slow)*1.5)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
        // Promoted up front, not when the movement starts. A window carries
        // real content, and leaving the compositor to raster it into its own
        // layer on the first animated frame is a visible hitch at exactly the
        // moment the deck is asking to be judged on its smoothness.
        "[will-change:transform,opacity] motion-reduce:[will-change:auto]",
        // A discarded window is the exception: it accelerates away instead of
        // coasting, so it reads as thrown rather than as placed.
        leaving &&
          "[transition-duration:calc(var(--nessa-motion-duration-slow)*0.95)] [transition-timing-function:cubic-bezier(0.4,0,0.7,0.2)]",
        // A drag tracks the pointer exactly; only its release is animated.
        dragging && "transition-none",
        // The deck clips its scroller, so the outline draws inset: an outset
        // ring on the edge pane would be cut off.
        "focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring",
        // Carousel: the focused window is at rest and its neighbours recede.
        mode === "carousel" &&
          (active
            ? "opacity-100"
            : "cursor-pointer translate-y-2 scale-90 opacity-40"),
        // Overview: every window is an equal, pointer-addressable tile.
        overview && (chrome ? "cursor-pointer shadow-xl" : "cursor-pointer"),
        // A pane that can be thrown owns the gesture outright: leaving the
        // browser its own panning would cancel the throw halfway.
        throwable && "touch-none",
        leaving && "pointer-events-none opacity-0",
        // The settle back to the carousel keeps the panes inert until it
        // lands, so a stray click cannot hit a surface that is still moving.
        settling && "pointer-events-none",
        className,
      )}
    >
      {header ? (
        <div
          data-slot="window-deck-pane-header"
          inert={contentInert}
          className={cn(
            "flex shrink-0 items-center gap-2 px-3 py-2",
            chrome && "border-b border-border",
            headerClassName,
          )}
        >
          {header}
        </div>
      ) : null}
      <div
        data-slot="window-deck-pane-content"
        inert={contentInert}
        className={cn(
          "min-h-0 flex-1",
          scrollable && "overflow-y-auto overscroll-contain",
          contentClassName,
        )}
      >
        {children}
      </div>
      {footer ? (
        <div
          data-slot="window-deck-pane-footer"
          inert={contentInert}
          className={cn(
            "flex shrink-0 items-center gap-2 px-3 py-2",
            chrome && "border-t border-border",
            footerClassName,
          )}
        >
          {footer}
        </div>
      ) : null}
    </div>
  )
}

export { WindowDeckPane, type WindowDeckPaneProps }

"use client"

/** @responsibility Coordinates pane registration, presentation mode, selection, and dismissal between a WindowDeck and its panes. */

import * as React from "react"

import type { WindowDeckTile } from "./window-deck-layout"

/** How the deck presents its panes. */
export type WindowDeckMode = "carousel" | "overview"

/** The edge a pane is thrown towards to dismiss it. */
export type WindowDeckDismissDirection = "up" | "down" | "left" | "right"

/** Why a pane was dismissed, and how far and fast it was thrown. */
export interface WindowDeckDismissal {
  /** The pane that left. */
  paneId: string
  /** The edge it was thrown towards. A shortcut reports the first direction the pane allows. */
  direction: WindowDeckDismissDirection
  /** Whether the user threw it or used the keyboard. */
  reason: "gesture" | "shortcut"
  /** How far it travelled before release, in pixels. Zero for a shortcut. */
  distance: number
  /** Its speed at release, in pixels per millisecond. Zero for a shortcut. */
  velocity: number
}

/** A pane registered with its owning deck. */
export interface RegisteredWindowDeckPane {
  /** The pane's unique id within the deck. */
  id: string
  /** The pane's rendered element, used for ordering and measurement. */
  element: HTMLElement
}

/** Shared state and handlers provided by one WindowDeck. */
export interface WindowDeckContextValue {
  /** How the deck currently presents its panes. */
  mode: WindowDeckMode
  /** The pane the carousel is centred on. */
  activePaneId: string | undefined
  /** The pane leaving the overview returns to, when nothing else is chosen. */
  restorePaneId: string | undefined
  /** Pane ids in visual order. */
  paneIds: readonly string[]
  /**
   * Whether the deck is mid-return from the overview. Panes stay
   * non-interactive across the settle so a stray click cannot land on a
   * surface that is still moving.
   */
  settling: boolean
  /** The overview transform for one pane, while the overview is open. */
  tileFor: (paneId: string) => WindowDeckTile | undefined
  /** Registers a pane; returns its disposer. */
  registerPane: (pane: RegisteredWindowDeckPane) => () => void
  /**
   * Opens one pane: centres it in the carousel, or returns the deck from the
   * overview to it.
   */
  selectPane: (paneId: string) => void
  /**
   * The pane the deck has asked to leave, from the keyboard, and a nonce
   * that makes each request distinct. The pane plays its own exit, so a
   * thrown pane and a dismissed one move identically.
   */
  dismissRequest: { paneId: string; nonce: number } | undefined
  /**
   * Told by a pane once it has finished playing a dismissal, and again if it
   * is still mounted afterwards — which is how the deck learns that the host
   * declined the removal and that there is nothing to announce or refocus.
   */
  reportDismissal: (paneId: string, outcome: "left" | "retained") => void
}

const WindowDeckContext = React.createContext<WindowDeckContextValue | null>(
  null,
)

/**
 * Reads the state of the nearest WindowDeck: which pane is focused, whether
 * the deck is a carousel or an overview, and how to open a pane. Content
 * inside a pane uses it to adapt to being a tile — a photograph dropping to
 * a thumbnail, a card hiding its call to action.
 *
 * @returns The current WindowDeck context value.
 * @throws When called outside a WindowDeck.
 */
function useWindowDeck(): WindowDeckContextValue {
  const context = React.useContext(WindowDeckContext)

  if (!context) {
    throw new Error("useWindowDeck must be used within a WindowDeck.")
  }

  return context
}

/**
 * Builds one ref callback that feeds an element to our internal ref and to a
 * ref the consumer may have passed, so neither side loses it.
 *
 * @param internal - The component's own element ref.
 * @param forwarded - The consumer's ref, if any.
 * @returns A ref callback serving both.
 */
function composeRefs<Element>(
  internal: React.RefObject<Element | null>,
  forwarded: React.Ref<Element> | undefined,
): React.RefCallback<Element> {
  return (element) => {
    internal.current = element

    if (typeof forwarded === "function") {
      forwarded(element)
    } else if (forwarded) {
      forwarded.current = element
    }
  }
}

/**
 * Orders registered panes by their position in the document, so pane order
 * always matches what the user sees regardless of mount order.
 *
 * @param panes - The registered panes to order.
 * @returns The panes sorted in document order.
 */
function sortByDocumentPosition(
  panes: readonly RegisteredWindowDeckPane[],
): RegisteredWindowDeckPane[] {
  return [...panes].sort((a, b) => {
    const position = a.element.compareDocumentPosition(b.element)

    if (position & Node.DOCUMENT_POSITION_FOLLOWING) return -1
    if (position & Node.DOCUMENT_POSITION_PRECEDING) return 1
    return 0
  })
}

export {
  WindowDeckContext,
  composeRefs,
  sortByDocumentPosition,
  useWindowDeck,
}

/** @responsibility The WindowDeck's overview geometry: how many columns a viewport takes, and the transform that carries each pane from its carousel position to its tile. */

/** A measured rectangle, in viewport pixels. */
export interface WindowDeckRect {
  /** Distance from the viewport's left edge to the rectangle's left edge. */
  left: number
  /** Distance from the viewport's top edge to the rectangle's top edge. */
  top: number
  /** The rectangle's width. */
  width: number
  /** The rectangle's height. */
  height: number
}

/** The space the overview grid is laid out inside, in pixels. */
export interface WindowDeckViewport {
  /** Usable width. */
  width: number
  /** Usable height. */
  height: number
}

/** Space reserved around the overview grid, in pixels. */
export interface WindowDeckOverviewInsets {
  /** Space above the first row. */
  top: number
  /** Space below the last row, where a host's dock or composer would sit. */
  bottom: number
  /** Space at each side of the grid. */
  horizontal: number
}

/** How the overview grid is proportioned. */
export interface WindowDeckOverviewOptions {
  /**
   * Column count. Omit to derive it from the viewport width and the size of
   * the deck: a small deck takes two columns below 720px and three above it,
   * and a larger one takes as many columns as it needs to stay within
   * `maxRows`, so tiles stop shrinking once the grid is deep.
   */
  columns?: number
  /**
   * How many rows the grid may use before it widens instead of shrinking.
   * @defaultValue 3, or 4 below 720px
   */
  maxRows?: number
  /** Space between tiles, both axes. @defaultValue 28 */
  gap?: number
  /**
   * Space around the grid. Raise `bottom` when the host draws a dock or a
   * composer over the deck, so the tiles are not laid out underneath it.
   * @defaultValue 32 top and bottom, responsive sides
   */
  insets?: Partial<WindowDeckOverviewInsets>
  /**
   * The smallest a tile may be scaled to before the deck reports that it has
   * no room for an overview at all. Below this a tile carries no readable
   * content and is barely a pointer target.
   * @defaultValue 0.12
   */
  minScale?: number
}

/** The transform that moves one pane from where it sits to its tile. */
export interface WindowDeckTile {
  /** Horizontal translation, in pixels. */
  x: number
  /** Vertical translation, in pixels. */
  y: number
  /** Uniform scale factor. */
  scale: number
}

/** The smallest tile the overview will present, as a scale factor. */
const MIN_TILE_SCALE = 0.12

/** The narrow viewport below which the overview drops to two columns. */
const NARROW_VIEWPORT = 720

/**
 * Chooses a column count for the overview.
 *
 * @param count - How many panes the deck holds.
 * @param viewportWidth - The width the grid is laid out inside.
 * @returns At least one column, and never more than there are panes.
 */
export function computeOverviewColumns(
  count: number,
  viewportWidth: number,
  maxRows?: number,
): number {
  if (count <= 0) return 0

  const narrow = viewportWidth < NARROW_VIEWPORT
  const rows = Math.max(1, Math.floor(maxRows ?? (narrow ? 4 : 3)))
  const base = narrow ? 2 : 3

  // A deck deeper than the grid allows widens rather than shrinking: one
  // viewport height divided by an unbounded row count is how an overview of
  // twenty windows ends up as a field of unreadable smudges.
  return Math.max(1, Math.min(count, Math.max(base, Math.ceil(count / rows))))
}

/**
 * Resolves the insets the grid is laid out inside, filling anything the host
 * left unspecified with the responsive defaults.
 *
 * @param viewportWidth - The width the grid is laid out inside.
 * @param insets - The host's partial override.
 * @returns Every inset, in pixels.
 */
function resolveInsets(
  viewportWidth: number,
  insets: Partial<WindowDeckOverviewInsets> | undefined,
): WindowDeckOverviewInsets {
  const narrow = viewportWidth < NARROW_VIEWPORT

  return {
    top: insets?.top ?? 32,
    // Symmetric by default. A deck is not assumed to have a dock or a
    // composer under it; a host that puts one there says so, and everything
    // else gets a grid that sits in the middle of its box rather than one
    // pushed up against the top edge with a band of dead space below it.
    bottom: insets?.bottom ?? 32,
    horizontal:
      insets?.horizontal ?? (narrow ? 20 : Math.max(48, viewportWidth * 0.07)),
  }
}

/**
 * Places every pane on the overview grid.
 *
 * Each pane is translated so its centre lands on its tile's centre and scaled
 * by one factor shared across the deck, so tiles read as the same surface
 * shrunk rather than as separately fitted boxes. The transform is relative to
 * where the pane currently sits, which is what a CSS transform applies to.
 *
 * @param rects - Each pane's current rectangle, in pane order.
 * @param viewport - The space the grid is laid out inside.
 * @param options - Column, gap, and inset overrides.
 * @returns One transform per pane, in the order the rectangles arrived; an
 * empty array when there are no panes, and `null` when the deck is too small
 * to hold a grid at all — a caller that gets `null` must stay in the
 * carousel rather than present an overview nobody can read or scroll.
 */
export function computeOverviewTiles(
  rects: readonly WindowDeckRect[],
  viewport: WindowDeckViewport,
  options: WindowDeckOverviewOptions = {},
): WindowDeckTile[] | null {
  if (rects.length === 0) return []

  const columns =
    options.columns !== undefined
      ? Math.max(1, Math.min(rects.length, Math.floor(options.columns)))
      : computeOverviewColumns(rects.length, viewport.width, options.maxRows)
  const rows = Math.ceil(rects.length / columns)
  const gap = options.gap ?? 28
  const insets = resolveInsets(viewport.width, options.insets)

  const tileWidth =
    (viewport.width - insets.horizontal * 2 - gap * (columns - 1)) / columns
  const tileHeight =
    (viewport.height - insets.top - insets.bottom - gap * (rows - 1)) / rows

  // No room for a grid. Returning identity transforms here would leave the
  // deck in a mode where nothing has moved, snapping is off, and the panes
  // beyond the fold cannot be reached at all.
  if (tileWidth <= 0 || tileHeight <= 0) return null

  // One factor for the whole deck: the pane that fits least generously sets
  // it, so no tile overflows its cell and none is scaled differently.
  const scale = rects.reduce((smallest, rect) => {
    if (rect.width <= 0 || rect.height <= 0) return smallest

    return Math.min(smallest, tileWidth / rect.width, tileHeight / rect.height)
  }, Number.POSITIVE_INFINITY)
  const uniformScale = Number.isFinite(scale) ? Math.min(scale, 1) : 1

  // Too small to be an overview. A grid of unreadable smudges is worse than
  // staying in the carousel, so the caller is told there is no room.
  if (uniformScale < (options.minScale ?? MIN_TILE_SCALE)) return null

  return rects.map((rect, index) => {
    const column = index % columns
    const row = Math.floor(index / columns)
    // The final row is centred when it is short, so a deck of five reads as a
    // composition rather than as a grid with a hole in the corner.
    const columnsInRow = Math.min(columns, rects.length - row * columns)
    const rowWidth = columnsInRow * tileWidth + (columnsInRow - 1) * gap
    const rowLeft = (viewport.width - rowWidth) / 2

    const tileCentreX = rowLeft + column * (tileWidth + gap) + tileWidth / 2
    const tileCentreY = insets.top + row * (tileHeight + gap) + tileHeight / 2

    return {
      x: tileCentreX - (rect.left + rect.width / 2),
      y: tileCentreY - (rect.top + rect.height / 2),
      scale: uniformScale,
    }
  })
}

"use client"

/** @responsibility Reads how long an element's transition actually runs, so the deck can wait a movement out on whatever duration the theme or the host applied. */

/**
 * The longest transition an element runs, including its delay.
 *
 * A movement is never waited out on a hard-coded duration: the theme zeroes
 * the motion tokens under `prefers-reduced-motion`, and a host may lengthen
 * or shorten them. A caller that receives 0 must complete its work
 * immediately rather than wait for a `transitionend` that will never arrive.
 *
 * @param element - The element whose transition is being measured.
 * @returns The duration in milliseconds, or 0 when nothing transitions.
 */
export function longestTransitionMs(element: HTMLElement): number {
  const style = window.getComputedStyle(element)
  const durations = style.transitionDuration.split(",")
  const delays = style.transitionDelay.split(",")

  return durations.reduce((longest, duration, index) => {
    const total =
      Number.parseFloat(duration) * 1000 +
      Number.parseFloat(delays[index] ?? delays[0] ?? "0") * 1000

    return Number.isFinite(total) ? Math.max(longest, total) : longest
  }, 0)
}

/** @responsibility The WindowDeck's keyboard contract: the shortcut descriptor shape, the default keymap, and the matcher that honours it. */

/** The primary modifier a shortcut may require. */
export type WindowDeckShortcutModifier = "control" | "meta" | "mod"

/** Describes one exact keyboard shortcut, in the design system's shape. */
export interface WindowDeckKeyboardShortcut {
  /** KeyboardEvent key, matched without case sensitivity. */
  key: string
  /**
   * Primary modifier. `mod` accepts exactly one of Meta or Control; omit
   * for neither.
   * @defaultValue undefined
   */
  modifier?: WindowDeckShortcutModifier
  /**
   * Whether Alt must be pressed.
   * @defaultValue false
   */
  altKey?: boolean
  /**
   * Whether Shift must be pressed.
   * @defaultValue false
   */
  shiftKey?: boolean
  /**
   * Prevents the matched browser event by default. Set false to keep it.
   * @defaultValue true
   */
  preventDefault?: boolean
}

/**
 * The deck's shortcut map. Every action ships a default; a host replaces any
 * entry with its own shortcut or `false` to disable it, and `shortcuts={false}`
 * on the deck turns the whole map off.
 */
export interface WindowDeckShortcuts {
  /** Switches between the carousel and the overview. @defaultValue `Mod+G` */
  toggleOverview?: WindowDeckKeyboardShortcut | false
  /** Moves to the next pane. @defaultValue `Mod+ArrowRight` */
  nextPane?: WindowDeckKeyboardShortcut | false
  /** Moves to the previous pane. @defaultValue `Mod+ArrowLeft` */
  previousPane?: WindowDeckKeyboardShortcut | false
  /**
   * Dismisses the focused pane from the overview, for hosts that made it
   * dismissible. The keyboard equivalent of throwing a tile off the top.
   * @defaultValue `Mod+Backspace`
   */
  dismissPane?: WindowDeckKeyboardShortcut | false
}

/** One action the deck's keymap can name. */
export type WindowDeckShortcutAction = keyof WindowDeckShortcuts

/** The keymap applied when a host names no shortcuts of its own. */
export const DEFAULT_WINDOW_DECK_SHORTCUTS: Required<WindowDeckShortcuts> =
  Object.freeze({
    toggleOverview: Object.freeze({ key: "g", modifier: "mod" }),
    nextPane: Object.freeze({ key: "ArrowRight", modifier: "mod" }),
    previousPane: Object.freeze({ key: "ArrowLeft", modifier: "mod" }),
    dismissPane: Object.freeze({ key: "Backspace", modifier: "mod" }),
  }) as Required<WindowDeckShortcuts>

/**
 * Merges a host's keymap over the defaults.
 *
 * @param shortcuts - The host's overrides, or false for no keyboard control.
 * @returns The resolved keymap, with a disabled action left as `false`.
 */
export function resolveWindowDeckShortcuts(
  shortcuts: WindowDeckShortcuts | false | undefined,
): Required<WindowDeckShortcuts> | false {
  if (shortcuts === false) return false
  if (!shortcuts) return DEFAULT_WINDOW_DECK_SHORTCUTS

  return {
    ...DEFAULT_WINDOW_DECK_SHORTCUTS,
    ...shortcuts,
  }
}

/**
 * Checks whether an event carries exactly the requested primary modifier
 * (Control / Meta), and no unrequested one.
 *
 * @param event - The keyboard event being checked.
 * @param modifier - The required primary modifier, or undefined for none.
 * @returns Whether the event satisfies the requested modifier.
 */
function matchesModifier(
  event: KeyboardEvent,
  modifier: WindowDeckShortcutModifier | undefined,
) {
  switch (modifier) {
    case "mod":
      return event.metaKey !== event.ctrlKey
    case "meta":
      return event.metaKey && !event.ctrlKey
    case "control":
      return event.ctrlKey && !event.metaKey
    case undefined:
      return !event.metaKey && !event.ctrlKey
    default: {
      const exhaustiveModifier: never = modifier
      return exhaustiveModifier
    }
  }
}

/**
 * Checks whether an event comes from a place where the user is typing, so a
 * plain single-character shortcut never steals a keystroke.
 *
 * @param event - The keyboard event being checked.
 * @returns Whether the event target consumes plain keystrokes for editing.
 */
export function isEditableShortcutTarget(event: KeyboardEvent): boolean {
  const target = event.target

  if (!(target instanceof HTMLElement)) return false

  return (
    target.isContentEditable ||
    target instanceof HTMLInputElement ||
    target instanceof HTMLTextAreaElement ||
    target instanceof HTMLSelectElement
  )
}

/**
 * Checks one keyboard event against one shortcut descriptor.
 *
 * @param event - The keyboard event being checked.
 * @param shortcut - The descriptor to match, or false when disabled.
 * @returns Whether the event is exactly this shortcut. A disabled shortcut,
 * and a bare single-character shortcut pressed while typing, never match.
 */
export function matchesWindowDeckShortcut(
  event: KeyboardEvent,
  shortcut: WindowDeckKeyboardShortcut | false | undefined,
): boolean {
  if (!shortcut) return false
  if (
    shortcut.modifier === undefined &&
    shortcut.key.length === 1 &&
    isEditableShortcutTarget(event)
  ) {
    return false
  }

  return (
    event.key.toLowerCase() === shortcut.key.toLowerCase() &&
    matchesModifier(event, shortcut.modifier) &&
    event.altKey === Boolean(shortcut.altKey) &&
    event.shiftKey === Boolean(shortcut.shiftKey)
  )
}
